-- Environment context schema. Generated by go run ./cmd/environment-schema.
CREATE TABLE IF NOT EXISTS "environment_object" ("id" bigserial,"group_id" bigint,"name" varchar(160),"kind" varchar(32),"description" text,"revision" bigint,"deleted" boolean,"updated_at" bigint,PRIMARY KEY ("id"));
CREATE INDEX IF NOT EXISTS "idx_environment_object_deleted" ON "environment_object" ("deleted");
CREATE INDEX IF NOT EXISTS "idx_environment_object_group_id" ON "environment_object" ("group_id");
CREATE TABLE IF NOT EXISTS "environment_relation" ("id" bigserial,"identity" varchar(64),"from_ref" varchar(100),"to_ref" varchar(100),"kind" varchar(32),"status" varchar(24),"from_version" varchar(64),"to_version" varchar(64),"source" varchar(32),"note" text,"valid_until" bigint,"created_by" bigint,"updated_by" bigint,"updated_at" bigint,"revision" bigint,PRIMARY KEY ("id"),CONSTRAINT "uni_environment_relation_identity" UNIQUE ("identity"));
CREATE INDEX IF NOT EXISTS "idx_environment_relation_status" ON "environment_relation" ("status");
CREATE INDEX IF NOT EXISTS "idx_environment_relation_to_ref" ON "environment_relation" ("to_ref");
CREATE INDEX IF NOT EXISTS "idx_environment_relation_from_ref" ON "environment_relation" ("from_ref");
CREATE TABLE IF NOT EXISTS "environment_change" ("id" bigserial,"relation_id" bigint,"object_ref" varchar(100),"actor_id" bigint,"action" varchar(32),"detail" text,"created_at" bigint,PRIMARY KEY ("id"));
CREATE INDEX IF NOT EXISTS "idx_environment_change_created_at" ON "environment_change" ("created_at");
CREATE INDEX IF NOT EXISTS "idx_environment_change_object_ref" ON "environment_change" ("object_ref");
CREATE INDEX IF NOT EXISTS "idx_environment_change_relation_id" ON "environment_change" ("relation_id");
CREATE TABLE IF NOT EXISTS "environment_discovery" ("version_id" bigint,"actor_id" bigint,"state" varchar(24),"note" text,"next_run" bigint,"lease_until" bigint,"updated_at" bigint,PRIMARY KEY ("version_id"));
CREATE INDEX IF NOT EXISTS "idx_environment_discovery_next_run" ON "environment_discovery" ("next_run");
